1	export type Cell = [number, number];
2	
3	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighborsOf = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	// Rule 2: a live cell with two or three live neighbors lives on.
17	// Rules 1 and 3 are the complement: fewer than two is underpopulation,
18	// more than three is overpopulation, and either way the cell dies.
19	const survives = (liveNeighbors: number): boolean =>
20	  liveNeighbors === 2 || liveNeighbors === 3;
21	
22	// Rule 4: a dead cell with exactly three live neighbors becomes alive.
23	const isBorn = (liveNeighbors: number): boolean => liveNeighbors === 3;
24	
25	// Only a live cell or a neighbor of one can be alive next generation;
26	// every other cell has no live neighbors and stays dead.
27	const candidatesFrom = (liveCells: Cell[]): Cell[] =>
28	  deduplicate(liveCells.flatMap((cell) => [cell, ...neighborsOf(cell)]));
29	
30	const deduplicate = (cells: Cell[]): Cell[] => [
31	  ...new Map(cells.map((cell) => [keyOf(cell), cell])).values(),
32	];
33	
34	// Membership test over the current generation, by canonical coordinate key.
35	const aliveIn = (liveCells: Cell[]): ((cell: Cell) => boolean) => {
36	  const living = new Set(liveCells.map(keyOf));
37	  return (cell) => living.has(keyOf(cell));
38	};
39	
40	export function nextGeneration(liveCells: Cell[]): Cell[] {
41	  const isAlive = aliveIn(liveCells);
42	
43	  const isAliveNextGeneration = (cell: Cell): boolean => {
44	    const liveNeighbors = neighborsOf(cell).filter((n) => isAlive(n)).length;
45	    return isAlive(cell) ? survives(liveNeighbors) : isBorn(liveNeighbors);
46	  };
47	
48	  return candidatesFrom(liveCells).filter((cell) =>
49	    isAliveNextGeneration(cell),
50	  );
51	}
