37	        [1, 1],
38	      ]),
39	    );
40	  });
41	
42	  it("Rule 2 Survival: a live cell with 3 live neighbors lives on — (1,1) in ###/.#./... survives", () => {
43	    const result = nextGeneration([
44	      [0, 0],
45	      [1, 0],
46	      [2, 0],
47	      [1, 1],
48	    ]);
49	
